L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "\230\136\166\233\151\152\231\148\168\228\186\186\229\183\165\231\159\165\232\131\189\227\129\175\227\129\169\227\130\147\227\129\170\230\136\166\230\179\129\227\129\167\227\130\130\229\139\149\230\143\186\227\129\151\227\129\166\227\129\175\227\129\132\227\129\145\227\129\190\227\129\155\227\130\147\227\128\130\227\129\157\227\129\134\227\129\149\227\129\155\227\129\159\227\129\174\227\129\175\227\129\130\227\129\170\227\129\159\227\129\167\227\129\153\227\128\130"
